import{_ as t,o as s,c as a,ag as o}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"Debugging WebSockets","description":"","frontmatter":{},"headers":[],"relativePath":"guides/debugging-websockets.md","filePath":"guides/debugging-websockets.md","lastUpdated":1772297611000}'),i={name:"guides/debugging-websockets.md"};function n(r,e,l,c,d,h){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="debugging-websockets" tabindex="-1">Debugging WebSockets <a class="header-anchor" href="#debugging-websockets" aria-label="Permalink to &quot;Debugging WebSockets&quot;">​</a></h1><p><strong>Difficulty:</strong> Intermediate | <strong>Time:</strong> 10 minutes</p><p>This tutorial shows you how to inspect WebSocket connections and their individual frames using NectoProxy. WebSockets are used for real-time communication in chat applications, live dashboards, multiplayer games, and collaborative tools. Debugging them requires specialized tooling, and NectoProxy provides it.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>NectoProxy installed and running</li><li>CA certificate installed in your browser</li><li>Browser configured to use the proxy (port 8888)</li><li>An application that uses WebSockets</li></ul><h2 id="how-websocket-proxying-works" tabindex="-1">How WebSocket Proxying Works <a class="header-anchor" href="#how-websocket-proxying-works" aria-label="Permalink to &quot;How WebSocket Proxying Works&quot;">​</a></h2><p>When your browser opens a WebSocket connection through NectoProxy:</p><ol><li>The browser sends an HTTP <code>Upgrade</code> request (the WebSocket handshake).</li><li>NectoProxy intercepts this request and establishes a WebSocket connection to the upstream server.</li><li>NectoProxy acts as a relay, forwarding frames in both directions while capturing a copy of each frame.</li><li>The connection appears in the NectoProxy traffic list with the protocol column showing <strong>WS</strong> (for <code>ws://</code>) or <strong>WSS</strong> (for <code>wss://</code>).</li></ol><h2 id="step-1-configure-your-proxy" tabindex="-1">Step 1: Configure Your Proxy <a class="header-anchor" href="#step-1-configure-your-proxy" aria-label="Permalink to &quot;Step 1: Configure Your Proxy&quot;">​</a></h2><p>Ensure NectoProxy is running and your browser is configured to use it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nectoproxy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>The proxy captures WebSocket connections that pass through it automatically. No additional configuration is needed.</p><h2 id="step-2-open-your-websocket-application" tabindex="-1">Step 2: Open Your WebSocket Application <a class="header-anchor" href="#step-2-open-your-websocket-application" aria-label="Permalink to &quot;Step 2: Open Your WebSocket Application&quot;">​</a></h2><p>Open the application that uses WebSockets in your browser. For example:</p><ul><li>A chat application</li><li>A real-time dashboard</li><li>A live notification feed</li><li>A collaborative editing tool</li></ul><p>If you do not have a WebSocket application handy, you can test with a simple example:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Open your browser console and run:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> WebSocket</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wss://echo.websocket.org&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onopen</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Connected&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ws.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Hello NectoProxy!&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ws.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onmessage</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">event</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Received:&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, event.data);</span></span></code></pre></div><h2 id="step-3-find-websocket-traffic" tabindex="-1">Step 3: Find WebSocket Traffic <a class="header-anchor" href="#step-3-find-websocket-traffic" aria-label="Permalink to &quot;Step 3: Find WebSocket Traffic&quot;">​</a></h2><p>In the NectoProxy traffic list:</p><ol><li>Look for entries where the <strong>Protocol</strong> column shows <strong>WS</strong> or <strong>WSS</strong>.</li><li>Alternatively, the <strong>Status</strong> column will show <strong>101</strong> (Switching Protocols) for the initial WebSocket handshake.</li><li>The <strong>Method</strong> column typically shows <strong>GET</strong> (the initial upgrade request).</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the filter bar at the top of the traffic list to filter by protocol. Type <code>ws</code> or <code>wss</code> to show only WebSocket connections, reducing noise from regular HTTP traffic.</p></div><h2 id="step-4-view-websocket-frames" tabindex="-1">Step 4: View WebSocket Frames <a class="header-anchor" href="#step-4-view-websocket-frames" aria-label="Permalink to &quot;Step 4: View WebSocket Frames&quot;">​</a></h2><p>Click on a WebSocket entry in the traffic list to open the detail panel. You will see:</p><h3 id="connection-details" tabindex="-1">Connection Details <a class="header-anchor" href="#connection-details" aria-label="Permalink to &quot;Connection Details&quot;">​</a></h3><p>The request tab shows the initial WebSocket handshake:</p><ul><li><strong>URL:</strong> The WebSocket endpoint (e.g., <code>wss://api.example.com/socket</code>)</li><li><strong>Request Headers:</strong> Including <code>Upgrade: websocket</code>, <code>Connection: Upgrade</code>, <code>Sec-WebSocket-Key</code>, and <code>Sec-WebSocket-Version</code></li><li><strong>Status:</strong> <code>101 Switching Protocols</code></li></ul><h3 id="frame-list" tabindex="-1">Frame List <a class="header-anchor" href="#frame-list" aria-label="Permalink to &quot;Frame List&quot;">​</a></h3><p>The WebSocket frames tab shows all messages exchanged over the connection:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Timestamp</strong></td><td>When the frame was sent or received</td></tr><tr><td><strong>Direction</strong></td><td>Arrow indicating client-to-server or server-to-client</td></tr><tr><td><strong>Opcode</strong></td><td>The WebSocket frame type (see table below)</td></tr><tr><td><strong>Data</strong></td><td>The frame payload (text or binary)</td></tr><tr><td><strong>Length</strong></td><td>Size of the frame data in bytes</td></tr></tbody></table><h2 id="step-5-understanding-frame-data" tabindex="-1">Step 5: Understanding Frame Data <a class="header-anchor" href="#step-5-understanding-frame-data" aria-label="Permalink to &quot;Step 5: Understanding Frame Data&quot;">​</a></h2><h3 id="frame-direction" tabindex="-1">Frame Direction <a class="header-anchor" href="#frame-direction" aria-label="Permalink to &quot;Frame Direction&quot;">​</a></h3><p>Each frame has a direction indicator:</p><table tabindex="0"><thead><tr><th>Symbol</th><th>Meaning</th></tr></thead><tbody><tr><td>Client-to-Server</td><td>Message sent from the browser to the server</td></tr><tr><td>Server-to-Client</td><td>Message sent from the server to the browser</td></tr></tbody></table><h3 id="frame-opcodes" tabindex="-1">Frame Opcodes <a class="header-anchor" href="#frame-opcodes" aria-label="Permalink to &quot;Frame Opcodes&quot;">​</a></h3><p>WebSocket frames have an opcode that indicates the type of data:</p><table tabindex="0"><thead><tr><th>Opcode</th><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><code>1</code></td><td>Text</td><td>UTF-8 text data (most common for JSON APIs)</td></tr><tr><td><code>2</code></td><td>Binary</td><td>Binary data (used for file transfers, protobuf, etc.)</td></tr><tr><td><code>8</code></td><td>Close</td><td>Connection close frame</td></tr><tr><td><code>9</code></td><td>Ping</td><td>Keep-alive ping from either side</td></tr><tr><td><code>10</code></td><td>Pong</td><td>Response to a ping</td></tr></tbody></table><h3 id="reading-frame-data" tabindex="-1">Reading Frame Data <a class="header-anchor" href="#reading-frame-data" aria-label="Permalink to &quot;Reading Frame Data&quot;">​</a></h3><ul><li><strong>Text frames (opcode 1):</strong> Displayed as readable text. JSON messages are formatted for easy reading.</li><li><strong>Binary frames (opcode 2):</strong> Displayed as base64-encoded data. The <code>isBinary</code> flag is set to <code>true</code>.</li><li><strong>Control frames (8, 9, 10):</strong> Usually have minimal or no payload.</li></ul><details class="details custom-block"><summary>Example: Chat Application Frames</summary><p>A typical chat application might show frames like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Client -&gt; Server] {&quot;type&quot;: &quot;message&quot;, &quot;text&quot;: &quot;Hello!&quot;, &quot;room&quot;: &quot;general&quot;}</span></span>
<span class="line"><span>[Server -&gt; Client] {&quot;type&quot;: &quot;message&quot;, &quot;from&quot;: &quot;alice&quot;, &quot;text&quot;: &quot;Hello!&quot;, &quot;room&quot;: &quot;general&quot;, &quot;timestamp&quot;: 1706900000}</span></span>
<span class="line"><span>[Server -&gt; Client] {&quot;type&quot;: &quot;presence&quot;, &quot;user&quot;: &quot;bob&quot;, &quot;status&quot;: &quot;online&quot;}</span></span>
<span class="line"><span>[Client -&gt; Server] {&quot;type&quot;: &quot;typing&quot;, &quot;room&quot;: &quot;general&quot;}</span></span></code></pre></div><p>Each of these is a separate WebSocket text frame captured by NectoProxy.</p></details><h2 id="step-6-filter-websocket-traffic" tabindex="-1">Step 6: Filter WebSocket Traffic <a class="header-anchor" href="#step-6-filter-websocket-traffic" aria-label="Permalink to &quot;Step 6: Filter WebSocket Traffic&quot;">​</a></h2><p>To focus on WebSocket connections in a busy traffic list:</p><ul><li><strong>Filter by protocol:</strong> Use the filter bar and type <code>ws</code> or <code>wss</code>.</li><li><strong>Filter by status:</strong> Filter for status <code>101</code> to find WebSocket handshakes.</li><li><strong>Filter by URL pattern:</strong> Enter part of the WebSocket endpoint URL.</li></ul><h2 id="common-websocket-issues-and-solutions" tabindex="-1">Common WebSocket Issues and Solutions <a class="header-anchor" href="#common-websocket-issues-and-solutions" aria-label="Permalink to &quot;Common WebSocket Issues and Solutions&quot;">​</a></h2><h3 id="connection-fails-to-establish" tabindex="-1">Connection Fails to Establish <a class="header-anchor" href="#connection-fails-to-establish" aria-label="Permalink to &quot;Connection Fails to Establish&quot;">​</a></h3><p><strong>Symptom:</strong> No <code>101 Switching Protocols</code> response; you see a <code>400</code> or <code>403</code> instead.</p><p><strong>Possible causes:</strong></p><ul><li>The server rejected the WebSocket handshake.</li><li>The <code>Origin</code> header is not allowed by the server&#39;s CORS policy.</li><li>A required authentication token is missing from the handshake request.</li></ul><p><strong>Debugging with NectoProxy:</strong> Check the request headers in the handshake to verify the <code>Origin</code>, <code>Cookie</code>, and any authentication headers are correct.</p><h3 id="connection-drops-unexpectedly" tabindex="-1">Connection Drops Unexpectedly <a class="header-anchor" href="#connection-drops-unexpectedly" aria-label="Permalink to &quot;Connection Drops Unexpectedly&quot;">​</a></h3><p><strong>Symptom:</strong> A close frame (opcode 8) appears, or frames stop flowing.</p><p><strong>Possible causes:</strong></p><ul><li>Server-side timeout due to inactivity (no ping/pong).</li><li>Network interruption.</li><li>Server-side error.</li></ul><p><strong>Debugging with NectoProxy:</strong> Look for the close frame&#39;s data payload, which may contain a close code and reason. Check the timing of the last frames to determine if inactivity caused the disconnect.</p><h3 id="messages-are-not-received" tabindex="-1">Messages Are Not Received <a class="header-anchor" href="#messages-are-not-received" aria-label="Permalink to &quot;Messages Are Not Received&quot;">​</a></h3><p><strong>Symptom:</strong> Client sends messages but receives no response, or vice versa.</p><p><strong>Possible causes:</strong></p><ul><li>The server is not handling the message format correctly.</li><li>Subscription or room setup was not completed.</li><li>Serialization mismatch (client sends JSON, server expects protobuf).</li></ul><p><strong>Debugging with NectoProxy:</strong> Compare the sent and received frames. Verify that the message format matches the server&#39;s expected schema.</p><h3 id="high-latency-on-messages" tabindex="-1">High Latency on Messages <a class="header-anchor" href="#high-latency-on-messages" aria-label="Permalink to &quot;High Latency on Messages&quot;">​</a></h3><p><strong>Symptom:</strong> Messages take a long time to appear.</p><p><strong>Debugging with NectoProxy:</strong> Compare the timestamps of client-to-server and server-to-client frames. Large gaps indicate server-side processing delays. Consistent small gaps are normal network latency.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Keep the traffic list focused</strong> by pausing recording when you are not actively debugging, then resuming when you want to capture a specific interaction.</li><li><strong>Use annotations</strong> to mark interesting WebSocket entries for later review. Right-click on an entry and add a note.</li><li><strong>WebSocket connections persist</strong> across many frames. A single entry in the traffic list may have hundreds or thousands of frames. Use the frame list&#39;s scroll or search to find specific messages.</li><li><strong>Binary WebSocket data</strong> (like protobuf or MessagePack) will appear as base64-encoded strings. You will need an external tool to decode the binary format.</li></ul>`,63)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
